coverage=[]
def seg(s): return [s.split('-')[0],s.split('-')[1]]
def M(p,e,faces=None,views=None,names=None,planar=False):
 d={'points':p,'edges':[seg(x) if isinstance(x,str) else x for x in e],'views':{'neutral':{'label':'Условие и построение'},**(views or {})},'labelNames':list(p) if names is None else names}
 if faces:d['faces']=faces
 if planar:d['planar']=True
 return d

def V(label,*edges,polygon=None,points=None):
 d={'label':label}
 if edges:d['segments']=[seg(e) if isinstance(e,str) else e for e in edges]
 if polygon:d['polygon']=polygon
 if points:d['points']=points
 return d

def plane(m,z=0):
 p=m['points']; xs=[v[0] for v in p.values()];ys=[v[1] for v in p.values()];w=max(max(xs)-min(xs),max(ys)-min(ys),1)*.2
 for k,v in zip(['q1','q2','q3','q4'],[[min(xs)-w,min(ys)-w,z],[max(xs)+w,min(ys)-w,z],[max(xs)+w,max(ys)+w,z],[min(xs)-w,max(ys)+w,z]]):p[k]=v
 m.setdefault('faces',[]).append(['q1','q2','q3','q4']);return m

def proj(top,foot,h,ends):
 p={top:[0,0,h],foot:[0,0,0]};e=[f'{top}-{foot}'];views={'height':V('Перпендикуляр к плоскости',f'{top}-{foot}')}
 for name,(x,y) in ends.items():p[name]=[x,y,0];e +=[f'{top}-{name}',f'{foot}-{name}'];views[name]=V('Наклонная и её проекция',f'{top}-{name}',f'{foot}-{name}')
 return plane(M(p,e,views=views))

def cube(a=1,b=None,c=None):
 b=a if b is None else b;c=a if c is None else c
 p={'A':[0,0,0],'B':[a,0,0],'C':[a,b,0],'D':[0,b,0],'A1':[0,0,c],'B1':[a,0,c],'C1':[a,b,c],'D1':[0,b,c]}
 return M(p,['A-B','B-C','C-D','D-A','A1-B1','B1-C1','C1-D1','D1-A1','A-A1','B-B1','C-C1','D-D1'],[['A','B','C','D']])

def add(m,p=None,e=None,views=None,faces=None):
 if p:m['points'].update(p);m['labelNames']+=list(p)
 if e:m['edges'] +=[seg(x) if isinstance(x,str) else x for x in e]
 if views:m['views'].update(views)
 if faces:m.setdefault('faces',[]).extend(faces)
 return m

def S(title,text,why=PYTH,view='neutral',prompt=None):return {'title':title,'prompt':prompt or ('Как обосновать шаг «'+title.lower()+'»?'),'explanation':text,'justifications':[{'kind':'theorem','text':why}],'view':view}
INDEX=json.loads((R/'stereo-course/merzlyak-10-base/source-index.json').read_text());SOURCES={e['source']['exercise']:e for e in INDEX['entries'] if e['id'].startswith('source-main-20-')}
def readable(x):
 if isinstance(x,str):return re.sub(r'([0-9°])(?=[А-Яа-яЁё])',r'\1 ',re.sub(r'([А-Яа-яЁё])(?=[0-9])',r'\1 ',x))
 if isinstance(x,list):return[readable(y)for y in x]
 if isinstance(x,dict):return{k:readable(v)for k,v in x.items()}
 return x
def save(n,title,statement,m,steps,answer,parts=None,caption=CAP,pages=None,hint=None):
 source=SOURCES[f'20.{n}'];pages=pages or source['source']['printedPages']
 for i,s in enumerate(steps,1):s['id']=f'step-{i}'
 lesson={'schemaVersion':1,'revision':1,'id':f'merz-ex-20-{n:03}','kind':'exercise','title':f'20.{n}. {title}','status':'draft','source':{'bookId':'merzlyak-2022-10-base','collection':'main','chapter':'Повторение курса','exercise':f'20.{n}','printedPages':pages,'pdfPages':[x+1 for x in pages]},'statement':{'text':statement,'goal':answer},'visualization':{'type':'scene3d','caption':caption,'model':m},'help':[{'id':'help-1','question':'С чего начать?','text':hint or steps[0]['explanation']}],'steps':steps,'answer':{'mode':'manual','prompt':'Запиши результат и обоснуй его. Доказательство и построение проверяет преподаватель. Ожидаемый вывод: '+answer},'review':{'source':'pending','mathematics':'pending','pedagogy':'pending'}}
 lesson=readable(lesson)
 path=f'stereo-course/merzlyak-10-base/lessons/ex-20-{n:03}.json';(R/path).write_text(json.dumps(lesson,ensure_ascii=False,indent=2)+'\n')
 coverage.append({'sourceEntryId':source['id'],'exercise':f'20.{n}','collection':'main','requiredParts':[None],'authoredSourceSubparts':parts or [],'sourcePrintedPages':pages,'sourcePdfPages':[x+1 for x in pages],'lessonFiles':[path],'status':'authored-draft','review':'pending'})
def finish():
 (R/'tools/merzlyak-10-base/coverage-20.json').write_text(json.dumps({'entries':coverage,'status':'authored-draft','sourceExceptions':[{'exercise':'20.58','kind':'missing-incidence','details':'Printed source omits C∈m. Card explicitly distinguishes the intended common-foot90° solution from literal insufficiency if skew perpendicular lines are allowed.'},{'exercise':'20.83','kind':'answer-key-order','details':'Source data fix AA1 internal dihedral60°,BB1 internal dihedral120°; printed answers list these in reverse order without edge labels. Card shows the derivation and labels the edges.'},{'exercise':'20.28','kind':'editorial-word','details':'Source calls a section of a tetrahedron although the defined solid is the five-vertex pyramid MABCD; the solution explicitly sections that pyramid.'}]},ensure_ascii=False,indent=2)+'\n')
 print('Authored §20 drafts:',len(coverage))
def tetra(a=4):return M({'A':[0,0,0],'B':[a,0,0],'C':[0,a,0],'D':[1,1,a]},['A-B','B-C','C-A','D-A','D-B','D-C'],[['A','B','C']])
def prism():
 p={'A':[0,0,0],'B':[4,0,0],'C':[0,3,0],'A1':[.5,.2,3],'B1':[4.5,.2,3],'C1':[.5,3.2,3]}
 return M(p,['A-B','B-C','C-A','A1-B1','B1-C1','C1-A1','A-A1','B-B1','C-C1'],[['A','B','C']])
def two_planes(h=3):
 p={'u1':[-4,-3,0],'u2':[4,-3,0],'u3':[4,3,0],'u4':[-4,3,0],'v1':[-4,-3,h],'v2':[4,-3,h],'v3':[4,3,h],'v4':[-4,3,h]}
 return M(p,[],[['u1','u2','u3','u4'],['v1','v2','v3','v4']],names=[])

