def general_prism(base,shift):
 names=list(base);p=dict(base)
 for k in names:p[k+'1']=[base[k][i]+shift[i]for i in range(3)]
 e=[[names[i],names[(i+1)%len(names)]]for i in range(len(names))]+[[names[i]+'1',names[(i+1)%len(names)]+'1']for i in range(len(names))]+[[k,k+'1']for k in names]
 return M(p,e,[names])
def pyramid(base,apex,top='M'):
 names=list(base);p=dict(base);p[top]=apex
 return M(p,[[names[i],names[(i+1)%len(names)]]for i in range(len(names))]+[[top,k]for k in names],[names])
def square_pyramid(a=4,h=None):return pyramid({'A':[-a/2,-a/2,0],'B':[a/2,-a/2,0],'C':[a/2,a/2,0],'D':[-a/2,a/2,0]},[0,0,h if h is not None else a/Q(2)])

