save(90,'Четыре двугранных угла пирамиды','Основание пирамиды — квадрат. Одно боковое ребро равно стороне квадрата и перпендикулярно основанию. Найдите двугранные углы при рёбрах основания.',m,[S('Введи обозначения','Пусть основание ABCD со стороной a, MA=a и MA⊥(ABCD). Грани MAB,MAD содержат перпендикуляр к основанию, поэтому двугранные углы при AB,AD равны90°.','Признак перпендикулярности плоскостей.','vertical'),S('Найди угол при BC','BA⊥BC и BM⊥BC по теореме о трёх перпендикулярах. Поэтому линейный угол при BC — ∠MBA. В прямоугольном равнобедренном MAB он равен45°.','Линейный угол двугранного угла.','angle'),S('Найди угол при CD','Аналогично ∠MDA — линейный угол при CD. MA=AD, поэтому он тоже45°.','Равнобедренный прямоугольный треугольник.','angle')],'При AB и AD —90°; при BC и CD —45°.')
m=pyramid({'A':[0,0,0],'B':[10,0,0],'C':[15,5*Q(3),0],'D':[5,5*Q(3),0]},[0,0,15]);p=m['points'];add(m,p={'H':foot(p['A'],p['B'],p['C']),'K':foot(p['A'],p['C'],p['D'])},e=['A-H','A-K','M-H','M-K'],views={'height':V('Высота и высоты боковых граней','M-A','A-H','M-H','A-K','M-K')})
save(91,'Боковая площадь пирамиды над ромбом с вершиной над A','В пирамиде MABCD основание — ромб: AB=10 см, ∠BAD=60°. Грани ABM,ADM перпендикулярны основанию; плоскости BCM,DCM образуют с основанием углы60°. Найдите боковую площадь.',m,[S('Найди проекцию вершины','Пересечение двух граней ABM,ADM, перпендикулярных основанию, — MA; значит MA⊥основанию. Расстояния от A до прямых BC,CD равны высоте ромба10sin60°=5√3.','Свойство двух перпендикулярных основанию плоскостей.'),S('Найди высоту и две боковые высоты','Для H — основания перпендикуляра из A к BC угол MHA=60°. Поэтому MA=AH tan60°=15. Высота MH боковой грани равна AH/cos60°=10√3. Для грани DCM получается такая же высота.','Теорема о трёх перпендикулярах и линейный угол.','height'),S('Вычисли площади четырёх граней','S_ABM=S_ADM=10·15/2=75. S_BCM=S_DCM=10·10√3/2=50√3 см².','Площадь треугольника.'),S('Сложи','S_бок=150+100√3=50(3+2√3) см².','Сумма площадей боковых граней.')],'50(3+2√3) см².')
finish()
